if [ "$(uname)" == "Darwin" -a "${PLAT}" == "x86_64" ]; then
    PYTHON="arch -x86_64 python"
else
    PYTHON=python
fi

if [ "${INTERFACE64}" != "1" ]; then
    module="scipy_openblas32"
else
    module="scipy_openblas64"
fi

# get_pkg_config reads from the original pc_file generated by the OpenBLAS build, so
# redirect the output to a temporary file and then rename it over the original.
pc_file="local/$module/lib/pkgconfig/scipy-openblas.pc"
PYTHONPATH=$PWD/local $PYTHON -c \
    "import $module as s; print(s.get_pkg_config(use_prefix=True))" \
    > "$pc_file.tmp"
mv "$pc_file.tmp" "$pc_file"
